<script setup>
import {ref} from 'vue';
import {brewApi} from '../api';
import JourneyDetailDialog from './JourneyDetailDialog.vue';
const props=defineProps({record:Object,kind:{type:String,default:'plan'}});
const emit=defineEmits(['changed']);
const action=ref(''),reason=ref(''),saving=ref(false),error=ref('');
function open(value){action.value=value;reason.value='';error.value='';}
async function submit(){if(saving.value)return;if(!reason.value.trim()){error.value='请填写原因';return;}saving.value=true;error.value='';try{if(props.kind==='demand')await brewApi.demandAction(props.record.id,action.value,props.record.version,reason.value.trim());else await brewApi.productionPlanAction(props.record.id,action.value,{version:props.record.version,reason:reason.value.trim()});action.value='';emit('changed');}catch(e){error.value=e.message;}finally{saving.value=false;}}
</script>
<template><div v-if="record?.can_close && !record.deleted_at" class="production-close-actions"><button v-if="!['cancelled','terminated'].includes(record.state)" type="button" @click="open('cancel')">取消{{ kind==='demand'?'需求':'计划' }}</button><button type="button" @click="open('delete')">删除{{ kind==='demand'?'需求':'计划' }}</button><JourneyDetailDialog v-if="action" :title="(action==='delete'?'删除':'取消')+(kind==='demand'?'产品需求':'生产计划')" :subtitle="record.name" @close="!saving&&(action='')"><p>{{ kind==='demand'?'关联的未关闭生产计划会一并取消，停止后续任务。':'将停止该计划的后续任务，并释放尚未使用的库存占用。' }}</p><p>已领原料、在罐酒液与已入库成品保留，退料或出酒需按实际办理。</p><p v-if="action==='delete'">删除后从列表移除，执行记录和删除原因仍可追溯。</p><label>原因<textarea v-model="reason" :disabled="saving" maxlength="2000" placeholder="填写本次处理原因" /></label><div v-if="error" role="alert" class="master-error">{{ error }}</div><template #footer><button type="button" class="btn btn-secondary" :disabled="saving" @click="action=''">返回</button><button type="button" class="btn btn-danger" :disabled="saving" @click="submit">{{ saving?'处理中…':action==='delete'?'确认删除':'确认取消' }}</button></template></JourneyDetailDialog></div></template>
<style scoped>.production-close-actions{display:flex;gap:14px;align-items:center}.production-close-actions>button{background:none;border:0;color:var(--text-muted);font:inherit;font-size:12px;cursor:pointer;padding:6px 0}.production-close-actions>button:last-of-type{color:#ce9586}.production-close-actions p{font-size:12px;color:var(--text-secondary);line-height:1.8}.production-close-actions label{display:grid;gap:8px;margin-top:20px;font-size:12px}.production-close-actions textarea{padding:10px;background:var(--bg-input);color:var(--text-primary);border:1px solid var(--border-default);border-radius:6px;min-height:90px;width:100%;box-sizing:border-box}.production-close-actions :deep(footer .btn+.btn){margin-left:10px}</style>
